 rgb=[v[:3] for im in raw.values() for v in im.getdata() if v[3]>=128];palImage=Image.new('RGB',(len(rgb),1));palImage.putdata(rgb);pal=palImage.quantize(colors=63,method=Image.Quantize.MEDIANCUT,dither=Image.Dither.NONE);full={};colors=set()
